/* ASIC-Skill .v and .sv examples with native HDL testbenches.
 * The RTL and native testbench sources originate from ASIC-Skill's 30-day
 * Verilog learning materials, not generated by changing a Python test to HDL. */
(function(root){'use strict';
const originals=root.ASIC_COCOTB_EXAMPLES||[];
const nativeTests=root.ASICRTL_WORKSHOP_TESTS||{};
function toSystemVerilog(source){
  // Preserve the original hardware behavior and use SystemVerilog variable types.
  // Keep all other syntax iverilog -g2012 compatible.
  return source.replace(/\breg\b/g,'logic').replace(/\bwire\b/g,'logic');
}
const library={verilog:[],systemverilog:[]};
for(const item of originals){
  const native=nativeTests[item.id];
  if(!native?.testbench||!native.test_top)continue;
  const v={...item,language:'verilog',test_top:native.test_top,native_test:native.testbench};
  const sv={...item,language:'systemverilog',rtl:toSystemVerilog(item.rtl),
      test_top:native.test_top,native_test:toSystemVerilog(native.testbench)};
  library.verilog.push(v);library.systemverilog.push(sv);
}
root.ASIC_COCOTB_HDL_LIBRARY=library;
})(window);
